#[derive(Deserialize)]
pub struct MouseProductSpec {
    product_id: u32,
    profile: Option<Value>,
    #[serde(default)]
    device_profile: Option<Value>,
    #[serde(default)]
    profile_schema_version: Option<u32>,
    min_dpi: u32,
    max_dpi: u32,
    dpi_step: u32,
    support_xy: bool,
    rates: BTreeMap<String, Vec<u32>>,
    effects: Vec<MouseEffect>,
    buttons: Vec<Value>,
    dkm: Vec<Value>,
    mats: Vec<Value>,
    calibration: String,
    smart_lift_max: u32,
    smart_landing_max: u32,
    power_slider: bool,
    performance_power: bool,
    low_power_slider: bool,
    low_battery_slider: bool,
    rotation: bool,
    dynamic: bool,
    pages: Vec<String>,
    image: Option<String>,
    groups: Vec<Value>,
    #[serde(default)]
    widget_column_layout: Option<String>,
    #[serde(default)]
    power_direct_widgets: bool,
}

#[derive(Deserialize)]
struct MouseEffect {
    key: String,
    id: u32,
}

impl MouseProductSpec {
    fn profile_defaults(&self) -> &Value {
        if self.product_id == 182 {
            static PROFILE: OnceLock<Value> = OnceLock::new();
            return PROFILE.get_or_init(razer_device::profile_transfer::default_profile_182);
        }
        self.profile
            .as_ref()
            .expect("Packaged mouse profile defaults are absent")
    }

    fn device_defaults(&self) -> Option<&Value> {
        if self.product_id == 182 {
            static DEVICE: OnceLock<Value> = OnceLock::new();
            return Some(DEVICE.get_or_init(razer_device::profile_transfer::default_device_182));
        }
        self.device_profile.as_ref()
    }

    pub(crate) fn profile_document_defaults(&self) -> Option<(&Value, &Value, u32)> {
        Some((
            self.profile_defaults(),
            self.device_defaults()?,
            self.profile_schema_version?,
        ))
    }
    fn block_widget_columns(&self) -> bool {
        self.widget_column_layout.as_deref() == Some("block")
    }
    pub fn macro_groups(&self) -> &[Value] {
        &self.groups
    }
    pub fn macro_image(&self) -> Option<&str> {
        self.image.as_deref()
    }
    fn has_page(&self, key: &str) -> bool {
        self.pages.iter().any(|p| p == key)
    }
    fn stages_path(&self) -> &'static str {
        if let Some(spec) = dpi_rows::source_spec(self.product_id) {
            return spec.stages_path();
        }
        if self.profile_defaults().get("DPIStages").is_some() {
            "/DPIStages/Stages/DPIStage"
        } else {
            "/dpiStages/stages"
        }
    }
    fn active_path(&self) -> &'static str {
        if let Some(spec) = dpi_rows::source_spec(self.product_id) {
            return spec.active_path();
        }
        if self.profile_defaults().get("DPIStages").is_some() {
            "/DPIStages/Active"
        } else {
            "/dpiStages/active"
        }
    }
    fn stage_enable_path(&self) -> &'static str {
        if let Some(spec) = dpi_rows::source_spec(self.product_id) {
            return spec.enabled_path();
        }
        if self.profile_defaults().get("DPIStages").is_some() {
            "/DPIStages/State"
        } else {
            "/dpiStages/enable"
        }
    }
    fn dpi_axis(&self, axis: usize) -> &'static str {
        if let Some(spec) = dpi_rows::source_spec(self.product_id) {
            return if axis == 0 { spec.x_key() } else { spec.y_key() };
        }
        match (self.profile_defaults().get("DPIStages").is_some(), axis) {
            (true, 0) => "X",
            (true, _) => "Y",
            (false, 0) => "x",
            (false, _) => "y",
        }
    }
    fn independent_key(&self) -> &'static str {
        if let Some(spec) = dpi_rows::source_spec(self.product_id) {
            return spec.independent_key();
        }
        if self.profile_defaults().get("DPIStages").is_some() {
            "Independent"
        } else {
            "independent"
        }
    }
    fn has_dpi_number(&self, path: &str) -> bool {
        dpi_rows::source_spec(self.product_id).is_some_and(|spec| spec.has_number(path))
    }
    fn dpi_grid_spec(&self) -> Option<&'static dpi_grid::GridSpec> {
        dpi_grid::source_spec(self.product_id)
    }
    fn visible_key(&self) -> &'static str {
        if let Some(spec) = dpi_rows::source_spec(self.product_id) {
            return spec.visible_key();
        }
        if self.profile_defaults().get("DPIStages").is_some() {
            "Active"
        } else {
            "visible"
        }
    }
    fn polling_path(&self) -> &'static str {
        if self.profile_defaults().get("PollingRate").is_some() {
            "/PollingRate"
        } else {
            "/pollingRate"
        }
    }
    fn power_path(&self) -> &'static str {
        if self.profile_defaults().get("PowerSavingValue").is_some() {
            "/PowerSavingValue"
        } else {
            "/powerSavingValue"
        }
    }
}

pub fn source_product(product_id: u32) -> Option<&'static MouseProductSpec> {
    static PRODUCTS: super::source_catalog::SourceCatalog<MouseProductSpec> =
        super::source_catalog::SourceCatalog::new(|| read_mouse_products_catalog());
    let product = PRODUCTS.get(product_id)?;
    product.profile_defaults();
    Some(product)
}
pub(crate) fn mapping_target_info(product_id: u32) -> Option<&'static Value> {
    lighting_effects::mapping_target_info(product_id)
}

